insert into public.levels(id,ord,title,src,theme_id) values('ia1',101,'Qu''est-ce que l''IA ?','Partie 1 · IA pour tous (Andrew Ng) · vocabulaire, forces et limites','ia') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src,theme_id=excluded.theme_id;
insert into public.levels(id,ord,title,src,theme_id) values('ia2',102,'Mener un projet d''IA','Partie 2 · IA pour tous (Andrew Ng) · étapes, choix du projet, équipe et outils','ia') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src,theme_id=excluded.theme_id;
insert into public.levels(id,ord,title,src,theme_id) values('ia3',103,'L''IA dans l''entreprise','Partie 3 · IA pour tous (Andrew Ng) · produits complexes, équipe, plan de transformation','ia') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src,theme_id=excluded.theme_id;
insert into public.questions values('ia1',0,'Les filtres antispam et la reconnaissance vocale d''aujourd''hui relèvent de quel type d''IA ?','["La superintelligence", "L''IA forte, déjà commercialisée", "L''IA générale (AGI), capable de tout faire comme un humain", "L''IA spécialisée (ANI), conçue pour une seule tâche"]'::jsonb,3,'Ce sont des IA spécialisées (ANI) : excellentes sur une tâche précise, incapables d''en faire une autre. L''IA générale (AGI) n''existe pas encore.');
insert into public.questions values('ia1',1,'Comment s''appelle la technique qui apprend à associer une entrée A à une sortie B ?','["L''apprentissage supervisé", "L''IA générale", "L''apprentissage non supervisé", "L''apprentissage par renforcement"]'::jsonb,0,'On donne au système des paires (A, B) et il apprend la correspondance. C''est la technique qui crée le plus de valeur économique aujourd''hui.');
insert into public.questions values('ia1',2,'Pour un filtre antispam, que sont A et B ?','["A = l''e-mail, B = « spam » ou « pas spam »", "A = « spam », B = l''e-mail", "A = l''heure d''envoi, B = l''adresse de l''expéditeur", "A = le texte, B = sa traduction"]'::jsonb,0,'L''entrée est l''e-mail, la sortie est l''étiquette à prédire. Même schéma ailleurs : audio → texte, image → « voiture ou pas ».');
insert into public.questions values('ia1',3,'Pour obtenir les meilleures performances d''un réseau de neurones en reconnaissance vocale, il faut :','["Peu de données et un petit réseau", "Beaucoup de données et un petit réseau", "Beaucoup de données et un grand réseau", "Peu de données et un grand réseau"]'::jsonb,2,'Un petit réseau plafonne vite, même avec beaucoup de données. Un grand réseau n''exprime sa puissance que s''il est nourri de beaucoup d''exemples.');
insert into public.questions values('ia1',4,'L''étiquetage manuel (un humain donne B pour chaque A) est la seule façon d''obtenir des données d''apprentissage.','["Vrai, sauf pour les images", "Faux : l''IA invente elle-même ses étiquettes B", "Vrai : seul un humain peut fournir B", "Faux : on peut aussi observer des comportements ou utiliser des données existantes"]'::jsonb,3,'On peut étiqueter à la main, mais aussi enregistrer ce que font les utilisateurs (achats, clics) ou récupérer des données déjà disponibles.');
insert into public.questions values('ia1',5,'Tu fabriques des scooters. Laquelle de ces données est non structurée ?','["La vitesse maximale de chaque modèle", "Le nombre de scooters vendus chaque semaine", "Les photos de tes scooters", "Le prix catalogue de chaque modèle"]'::jsonb,2,'Images, sons et texte libre sont non structurés. Un tableau de ventes, de vitesses ou de prix est une donnée structurée.');
insert into public.questions values('ia1',6,'Tu vends de la nourriture pour chats en ligne. Quel est un bon résultat d''un projet de data science ?','["Un filtre antispam pour la boîte de réception", "Un réseau de neurones qui imite le cerveau d''un chat", "Un diaporama proposant une nouvelle grille de prix pour vendre plus", "Une base d''images étiquetées « chat » et « pas chat »"]'::jsonb,2,'La data science produit des conclusions qui aident à décider, souvent présentées sous forme de diaporama. Une base d''images n''est qu''une matière première.');
insert into public.questions values('ia1',7,'Quelle est la différence principale entre machine learning et data science ?','["Le ML produit un logiciel qui tourne en continu ; la data science produit des conclusions pour décider", "La data science ne travaille que sur des images", "Le ML produit des diaporamas ; la data science produit des logiciels", "Ce sont deux noms pour la même chose"]'::jsonb,0,'Exemple maisons : le ML donne une appli qui estime le prix ; la data science découvre que rénover augmente le prix de 15 % et guide la décision de rénover.');
insert into public.questions values('ia1',8,'Comment ces termes s''emboîtent-ils ?','["L''IA fait partie du deep learning", "Le deep learning fait partie du machine learning, qui fait partie de l''IA", "Le machine learning fait partie du deep learning", "Deep learning et data science sont la même chose"]'::jsonb,1,'Tout algorithme de deep learning est un algorithme de machine learning, mais l''IA englobe aussi d''autres méthodes.');
insert into public.questions values('ia1',9,'Que dire de « deep learning » et « réseau de neurones » ?','["Le deep learning n''utilise jamais de réseaux de neurones", "Ils désignent des idées opposées", "Ils sont aujourd''hui pratiquement synonymes", "Un réseau de neurones est un vrai cerveau biologique"]'::jsonb,2,'Le deep learning utilise des réseaux de neurones à nombreuses couches. Le lien avec le cerveau est très vague : c''est une grande équation mathématique.');
insert into public.questions values('ia1',10,'Que font bien les entreprises performantes en IA ?','["Seulement ajouter un chatbot à leur site", "Tout cela : acquérir des données de façon stratégique, les unifier dans un entrepôt, repérer ce qui peut être automatisé", "Seulement acheter beaucoup de serveurs", "Seulement recruter un chercheur célèbre"]'::jsonb,1,'Données stratégiques, entrepôt unifié, automatisation, nouveaux rôles (ingénieur ML) et itération rapide : c''est l''ensemble qui fait la différence.');
insert into public.questions values('ia1',11,'Un centre commercial avec un site web n''est pas une entreprise Internet. Qu''en tire-t-on pour l''IA ?','["L''IA ne sert qu''aux entreprises Internet", "Une entreprise d''IA doit fermer ses magasins", "Utiliser quelques algorithmes ne suffit pas : il faut organiser l''entreprise autour de ce que l''IA fait bien", "Il suffit d''ajouter un réseau de neurones pour devenir une entreprise d''IA"]'::jsonb,2,'Comme Internet, l''IA change la façon de travailler : données unifiées, décisions plus décentralisées, tests rapides. Ajouter un outil ne transforme rien.');
insert into public.questions values('ia1',12,'Règle empirique : l''apprentissage supervisé peut probablement automatiser une tâche si…','["Un humain la fait en une seconde de réflexion ou moins", "On n''a aucune donnée sur elle", "Un humain met plusieurs heures à la faire", "Elle demande beaucoup de créativité"]'::jsonb,0,'Repérer une voiture, dire si une personne sourit ou classer un e-mail : quelques instants pour un humain, donc un bon candidat pour l''IA.');
insert into public.questions values('ia1',13,'Laquelle de ces tâches est trop difficile pour l''IA d''aujourd''hui ?','["Trier un e-mail : remboursement ou livraison", "Détecter les voitures sur une image", "Repérer une rayure sur un téléphone", "Rédiger seule un rapport d''analyse de marché de 50 pages"]'::jsonb,3,'Un long rapport demande une compréhension profonde et des heures de travail humain. Les trois autres sont des tâches courtes et bien définies.');
insert into public.questions values('ia1',14,'Pourquoi une voiture autonome ne lit-elle pas les gestes d''un agent ou d''un cycliste ?','["C''est trop simple pour valoir un modèle", "C''est interdit par le Code de la route", "Les caméras ne voient pas les mains", "Les gestes sont très variés, les données manquent et la sécurité exige une précision très élevée"]'::jsonb,3,'Même 10 000 vidéos ne couvrent pas toutes les façons de faire signe. Les voitures se concentrent donc sur la détection des objets (voitures, piétons).');
insert into public.questions values('ia1',15,'Une IA entraînée sur des radiographies de grande qualité est utilisée sur des clichés mal cadrés. Que se passe-t-il ?','["Ses performances chutent, car les données diffèrent de celles de l''entraînement", "Elle s''améliore toute seule", "Elle donne exactement les mêmes résultats", "Elle corrige le cadrage avant de répondre"]'::jsonb,0,'Un médecin s''adapte à un patient mal positionné ; l''IA, beaucoup moins. Elle fonctionne bien sur des données semblables à celles qu''elle a vues.');
insert into public.questions values('ia1',16,'Un jeune médecin comprend la pneumonie avec 10 images et un manuel. Et l''IA ?','["Elle a besoin de milliers d''images étiquetées et ne sait pas apprendre d''un texte descriptif", "Elle apprend encore plus vite que lui", "Elle n''a besoin d''aucune image", "Elle apprend mieux avec moins de 10 images"]'::jsonb,0,'L''humain apprend avec peu d''exemples et des explications. L''apprentissage supervisé, lui, réclame beaucoup de paires (image, diagnostic).');
insert into public.questions values('ia1',17,'Dans l''exemple des t-shirts, que fait le réseau le plus simple, à un seul neurone ?','["Il prend la demande et donne la couleur", "Il compte les t-shirts en stock", "Il dessine le logo du t-shirt", "Il prend le prix en entrée et donne la demande estimée"]'::jsonb,3,'Plus le prix monte, plus la demande baisse. Avec plus d''entrées (port, marketing, matière), on empile des neurones comme des briques de Lego.');
insert into public.questions values('ia1',18,'Comment un ordinateur « voit »-il une image ?','["Il reconnaît directement les yeux et le nez", "Comme un fichier son", "Comme une grille de nombres : la luminosité de chaque pixel, trois valeurs par pixel en couleur", "Comme une liste de mots décrivant l''image"]'::jsonb,2,'Une image couleur de 1000 × 1000 pixels donne 3 millions de nombres (rouge, vert, bleu) : c''est l''entrée A du réseau.');
insert into public.questions values('ia1',19,'Dans un réseau qui reconnaît des visages, que détectent les couches successives ?','["Toutes les couches font exactement la même chose", "D''abord les contours, puis les parties du visage, enfin le visage entier", "D''abord le nom, puis les yeux", "Seulement les couleurs de fond"]'::jsonb,1,'Personne ne dit au réseau de chercher un œil : il découvre seul cette hiérarchie à partir de milliers de photos étiquetées.');
insert into public.questions values('ia2',0,'Le machine learning est « itératif ». Qu''est-ce que cela veut dire ?','["La première idée fonctionne presque toujours", "On n''entraîne le modèle qu''une seule fois", "Une équipe essaie en général de nombreuses idées avant que l''une fonctionne", "Le modèle n''a jamais besoin de mise à jour"]'::jsonb,2,'La première version d''un modèle est souvent mauvaise. On teste, on ajuste, on recommence jusqu''à atteindre le niveau voulu.');
insert into public.questions values('ia2',1,'Tu veux trier automatiquement tes prospects commerciaux. Dans quel ordre procéder ?','["Collecter des données A et B, entraîner le modèle, puis le déployer", "Déployer, puis collecter, puis entraîner", "Entraîner, puis collecter, puis déployer", "Déployer directement sans données"]'::jsonb,0,'Les trois étapes d''un projet de ML : collecte (prospects et résultats passés), entraînement (A → B), déploiement, avec des itérations à chaque étape.');
insert into public.questions values('ia2',2,'Ton enceinte « Alexa » reconnaît mal les accents britanniques après son lancement. Que faire ?','["Collecter des enregistrements avec ces accents et mettre le modèle à jour", "Rien : un modèle déployé ne se modifie plus", "Demander aux utilisateurs de changer d''accent", "Retirer le produit du marché"]'::jsonb,0,'Le déploiement révèle des cas imprévus (accents, voiturettes de golf pour une voiture autonome). On renvoie ces nouvelles données dans l''entraînement.');
insert into public.questions values('ia2',3,'Quelles sont les étapes d''un projet de data science ?','["Collecter les données, les analyser, proposer des hypothèses et des actions, puis recommencer", "Collecter, entraîner, déployer un logiciel", "Écrire un diaporama sans regarder les données", "Acheter un GPU, coder, publier sur GitHub"]'::jsonb,0,'Après chaque action, on collecte de nouvelles données pour vérifier l''effet et réanalyser : c''est un cycle.');
insert into public.questions values('ia2',4,'Les visiteurs étrangers abandonnent ton panier de tasses à l''étape du paiement. Quelle action la data science peut-elle proposer ?','["Supprimer la page panier", "Tester l''intégration des frais de port dans le prix affiché", "Entraîner un réseau de neurones qui imite les clients", "Augmenter les frais de port"]'::jsonb,1,'L''analyse suggère que des frais de port élevés rebutent. Hypothèse → action → nouvelles données pour vérifier : c''est la démarche data science.');
insert into public.questions values('ia2',5,'Dans le recrutement, lequel de ces projets relève du machine learning plutôt que de la data science ?','["Comparer le taux d''acceptation des offres par service", "Trier automatiquement les CV des candidats", "Analyser pourquoi peu de candidats passent de l''entretien téléphonique à l''entretien sur site", "Présenter au comité un diaporama sur l''entonnoir de recrutement"]'::jsonb,1,'Le tri automatique de CV est un logiciel A → B ; il faut veiller aux biais. Les trois autres sont des analyses pour décider.');
insert into public.questions values('ia2',6,'En agriculture, qu''apporte le machine learning ?','["Remplacer le tracteur", "Choisir le nom de la ferme", "Prédire le prix d''une ferme sans aucune donnée", "Repérer les mauvaises herbes sur une photo et pulvériser seulement là"]'::jsonb,3,'C''est l''agriculture de précision : moins de désherbant, de meilleurs rendements. La data science, elle, conseille quoi planter et quand.');
insert into public.questions values('ia2',7,'Où se trouvent les meilleurs projets d''IA ?','["Là où personne de l''entreprise n''est impliqué", "À l''intersection de ce que l''IA sait faire et de ce qui compte pour ton activité", "Là où l''IA est la plus spectaculaire", "Dans les projets les plus longs"]'::jsonb,1,'On les trouve en réunissant des experts de l''IA et des experts du métier : ensemble, ils voient les deux cercles.');
insert into public.questions values('ia2',8,'Quel principe aide à trouver un bon projet d''IA ?','["Automatiser des tâches précises, pas des métiers entiers", "Vouloir remplacer un métier complet d''un coup", "Éviter de parler aux équipes concernées", "Choisir le projet le plus à la mode"]'::jsonb,0,'Un radiologue ne fait pas que lire des radios ; un centre d''appels a une tâche de routage automatisable. On liste les tâches et on cherche celles que l''IA peut prendre.');
insert into public.questions values('ia2',9,'Sans « big data », un projet de machine learning ne vaut pas la peine d''être lancé.','["Faux : on peut souvent démarrer avec peu de données, par exemple 100 à 1 000 photos", "Vrai : il faut au moins un million d''exemples", "Vrai, sauf pour la data science", "Faux : l''IA n''a jamais besoin de données"]'::jsonb,0,'Plus de données aide toujours, mais leur manque ne doit pas bloquer. Un expert en IA peut dire de combien le projet a besoin.');
insert into public.questions values('ia2',10,'Qu''est-ce qui fait partie de la diligence technique d''un projet ?','["Calculer seulement le chiffre d''affaires espéré", "Vérifier que la performance visée est atteignable, que les données existent et estimer le calendrier", "Choisir la couleur du logo", "Annoncer le projet aux clients"]'::jsonb,1,'Diligence technique : l''IA peut-elle le faire ? Précision atteignable, données nécessaires, délais et personnes.');
insert into public.questions values('ia2',11,'Qu''est-ce que la diligence commerciale ?','["S''assurer que le projet apportera de la valeur : coûts réduits, revenus en hausse ou nouvelle activité", "Tester le modèle sur l''ensemble de test", "Vérifier que la technologie est faisable", "Négocier le prix des GPU"]'::jsonb,0,'On construit des modèles financiers (feuilles de calcul) pour estimer économies et revenus. On y ajoute une réflexion éthique : le projet améliore-t-il la société ?');
insert into public.questions values('ia2',12,'Une solution standard du marché fait déjà ce dont tu as besoin. Que faire ?','["Attendre qu''elle disparaisse", "Courir plus vite que le train des grands acteurs", "La reconstruire en interne pour faire mieux", "L''acheter ou l''utiliser, et réserver le développement interne à ce qui t''est propre"]'::jsonb,3,'Ne cours pas devant un train : la solution standard finira par te dépasser. Développe en interne ce qui te donne un avantage unique.');
insert into public.questions values('ia2',13,'Pourquoi la data science se fait-elle plutôt en interne ?','["Elle n''utilise jamais de données", "Elle est interdite aux prestataires", "Elle est très liée à l''activité et demande de bien connaître l''entreprise", "Elle coûte toujours plus cher à l''extérieur"]'::jsonb,2,'Le machine learning peut être internalisé ou externalisé ; la data science exige une connaissance fine du métier.');
insert into public.questions values('ia2',14,'Que faut-il donner à une équipe d''IA pour cadrer un projet d''inspection de tasses ?','["Un objectif de 100 % de précision", "Seulement la date de livraison", "Un critère d''acceptation mesurable, comme 95 % de précision, et un ensemble de test", "Aucune donnée : elle se débrouillera"]'::jsonb,2,'Un objectif chiffré et des données pour le mesurer permettent de savoir si le système est prêt.');
insert into public.questions values('ia2',15,'À quoi sert l''ensemble d''apprentissage ?','["À présenter le projet aux investisseurs", "À entraîner l''algorithme avec des exemples A et leurs étiquettes B", "À mesurer la performance finale", "À stocker les mots de passe"]'::jsonb,1,'Pour le tri de CV : des CV (A) avec la décision souhaitée (B). C''est avec lui que l''algorithme apprend la règle.');
insert into public.questions values('ia2',16,'L''ensemble de test contient 3 tasses ; le système en classe 2 correctement. Quelle est sa précision ?','["66,7 %", "100 %", "95 %", "33,3 %"]'::jsonb,0,'2 sur 3. L''ensemble de test est différent de l''ensemble d''apprentissage, étiqueté lui aussi, et sert à mesurer la performance.');
insert into public.questions values('ia2',17,'Pourquoi viser 100 % de précision est-il souvent irréaliste ?','["Parce que les équipes d''IA sont paresseuses", "Tout cela : données insuffisantes, étiquettes fausses, cas ambigus, limites de la technologie", "Ce n''est jamais irréaliste", "Seulement parce que les GPU sont trop lents"]'::jsonb,1,'Une petite rayure peut être « OK » pour un expert et « défectueuse » pour un autre. Mieux vaut un objectif réaliste : un système à 95 % peut être très rentable.');
insert into public.questions values('ia2',18,'Quel matériel a rendu possible l''essor du deep learning ?','["Les imprimantes laser", "Les disquettes", "Les routeurs Wi-Fi", "Les processeurs graphiques (GPU)"]'::jsonb,3,'Conçus pour les jeux vidéo, les GPU (NVIDIA notamment) calculent très vite les grands réseaux de neurones. Le CPU gère les calculs généraux.');
insert into public.questions values('ia2',19,'Pourquoi une voiture autonome fait-elle ses calculs « en périphérie » (edge), dans la voiture ?','["Parce que le cloud n''existe pas pour les voitures", "Parce que c''est moins sûr", "Pour consommer plus de données réseau", "Pour décider en temps réel sans attendre une réponse du cloud"]'::jsonb,3,'Le calcul embarqué répond plus vite et envoie moins de données sur le réseau. Le cloud (AWS, Azure, GCP) offre de la puissance à la demande ; le sur site, plus de contrôle.');
insert into public.questions values('ia3',0,'Dans quel ordre fonctionne une enceinte connectée ?','["Exécution → intention → reconnaissance vocale → mot de réveil", "Mot de réveil → intention → reconnaissance vocale → exécution", "Mot de réveil → reconnaissance vocale → reconnaissance d''intention → exécution", "Reconnaissance vocale → mot de réveil → intention → exécution"]'::jsonb,2,'L''enceinte écoute « Hey terminal », transcrit la suite en texte, comprend ce qu''on veut, puis agit.');
insert into public.questions values('ia3',1,'« Raconte-moi une blague » : qu''est-ce qui choisit et lit la blague ?','["Du code logiciel classique, sans IA", "Un réseau de neurones géant", "Le mot de réveil", "Un algorithme d''apprentissage par renforcement"]'::jsonb,0,'Une fois l''intention reconnue, un module logiciel ordinaire pioche une blague dans une base et la lit.');
insert into public.questions values('ia3',2,'« Lance un minuteur de 10 minutes » : qu''a de plus cette commande ?','["Elle n''utilise pas la reconnaissance vocale", "Elle ne demande aucune exécution", "L''IA doit aussi extraire la durée « 10 minutes » du texte", "Elle n''a pas besoin de mot de réveil"]'::jsonb,2,'Il faut reconnaître l''intention « minuteur » et repérer l''information utile, la durée, quelle que soit la formulation.');
insert into public.questions values('ia3',3,'Avec quelle technique construit-on la détection des piétons d''une voiture autonome ?','["Les GAN", "L''apprentissage supervisé", "Un algorithme de planification de trajectoire", "L''apprentissage par renforcement"]'::jsonb,1,'Des milliers d''images où les piétons sont annotés : c''est du A → B. Les GAN génèrent des images, la planification décide de la trajectoire.');
insert into public.questions values('ia3',4,'À quoi sert la planification de trajectoire ?','["À transcrire les ordres vocaux", "À décider du chemin et de la vitesse sûrs, à partir de ce que la voiture perçoit et prévoit", "À fabriquer les cartes routières à la main", "À détecter les piétons"]'::jsonb,1,'Perception (que voit-on ?), prédiction (où iront-ils ?), planification (que fait-on ?), contrôle (volant, freins).');
insert into public.questions values('ia3',5,'Pourquoi une voiture autonome est-elle plus complexe qu''une enceinte connectée ?','["Elle n''utilise pas d''apprentissage automatique", "Elle utilise moins de capteurs", "Elle combine de nombreux capteurs et doit décider en temps réel avec des enjeux de sécurité", "Une erreur y est sans conséquence"]'::jsonb,2,'Caméras, LIDAR, radar, GPS : des données de plusieurs natures, des décisions en millisecondes, et une erreur peut être dangereuse.');
insert into public.questions values('ia3',6,'Tu construis un système de détection du mot de réveil. Qui recruter en priorité ?','["Un ingénieur de la donnée", "Un chercheur en machine learning", "Un ingénieur en machine learning", "Un chef de produit IA"]'::jsonb,2,'L''ingénieur ML construit et entraîne les modèles A → B. Le chercheur invente de nouveaux algorithmes, ce qui n''est pas nécessaire ici.');
insert into public.questions values('ia3',7,'Que fait un ingénieur de la donnée ?','["Il décide quoi construire", "Il stocke et organise de grands volumes de données de façon sûre, accessible et économique", "Il invente de nouveaux algorithmes", "Il écrit les blagues de l''enceinte"]'::jsonb,1,'Une voiture autonome produit des gigaoctets de données par minute : sans ingénieur de la donnée, impossible de les exploiter.');
insert into public.questions values('ia3',8,'Quel est le rôle du chef de produit IA ?','["Gérer les serveurs de stockage", "Décider quoi construire, en croisant ce qui est faisable et ce qui est utile", "Publier des articles de recherche", "Entraîner les modèles"]'::jsonb,1,'Il choisit par exemple les commandes prioritaires de l''enceinte selon les besoins des utilisateurs et les capacités de l''IA.');
insert into public.questions values('ia3',9,'Quelle part d''une équipe d''IA les ingénieurs logiciels représentent-ils souvent ?','["Aucune : ce ne sont pas des métiers de l''IA", "Exactement 10 %", "Moins de 5 %", "La moitié ou plus"]'::jsonb,3,'Ils écrivent tout le code qui entoure les modèles : exécution des commandes, contrôle du véhicule, intégration et fiabilité.');
insert into public.questions values('ia3',10,'Quelle est la première étape du plan de transformation par l''IA ?','["Nommer un directeur de l''IA", "Former tous les salariés", "Écrire la stratégie IA", "Lancer des projets pilotes pour prendre de l''élan"]'::jsonb,3,'Les cinq étapes : projets pilotes, équipe IA interne, formation, stratégie, communication.');
insert into public.questions values('ia3',11,'Qu''est-ce qui compte le plus pour le premier projet pilote ?','["Qu''il soit forcément réalisé par une équipe interne", "Qu''il soit le plus rentable possible dès le départ", "Qu''il dure au moins cinq ans", "Qu''il réussisse et montre des résultats en 6 à 12 mois, même s''il n''est pas le plus rentable"]'::jsonb,3,'Le pilote sert à faire tourner le moteur : prouver que l''IA marche et gagner la confiance. Il peut être externalisé si l''expertise manque.');
insert into public.questions values('ia3',12,'Comment organiser l''équipe IA interne ?','["Une équipe centrale qui travaille avec chaque unité, financée au départ par la direction", "Chaque service recrute seul ses ingénieurs IA, sans coordination", "Une équipe isolée qui ne parle à aucun service", "Aucune équipe : tout est sous-traité pour toujours"]'::jsonb,0,'Une équipe centralisée (souvent rattachée à un responsable IA, au CTO ou au CIO) en structure matricielle, qui crée des outils réutilisables.');
insert into public.questions values('ia3',13,'Combien de temps de formation pour chaque public, selon le plan ?','["Dirigeants 100 h, ingénieurs 4 h", "Dirigeants environ 4 h, managers environ 12 h, ingénieurs environ 100 h", "Tout le monde 100 h", "Aucune formation : l''IA s''explique d''elle-même"]'::jsonb,1,'Chacun apprend ce dont il a besoin : décider des investissements, piloter des projets, ou construire les systèmes. Les cours en ligne existants suffisent souvent.');
insert into public.questions values('ia3',14,'Pourquoi la stratégie IA n''est-elle pas la première étape ?','["Parce que la loi l''interdit", "Sans expérience concrète de l''IA, la stratégie risque d''être irréaliste ou vague", "Parce qu''une stratégie est inutile", "Parce qu''il faut d''abord communiquer à la presse"]'::jsonb,1,'Les pilotes, l''équipe et la formation apprennent d''abord ce que l''IA peut vraiment faire pour l''entreprise.');
insert into public.questions values('ia3',15,'Qu''est-ce que le cycle vertueux de l''IA ?','["Les données disparaissent après chaque utilisation", "Un meilleur produit attire plus d''utilisateurs, qui génèrent plus de données, qui améliorent le produit", "L''IA améliore seule son matériel", "Plus on dépense, plus l''IA devient gratuite"]'::jsonb,1,'Blue River l''a montré : quelques photos de cultures, un premier produit, des agriculteurs, plus de photos, un meilleur produit… et une avance difficile à rattraper.');
insert into public.questions values('ia3',16,'Quelles communications prévoit l''étape 5 ?','["Internes et externes : salariés, investisseurs, clients, régulateurs et candidats", "Seulement un communiqué de presse", "Seulement un message aux actionnaires", "Aucune : il vaut mieux rester discret"]'::jsonb,0,'Rassurer les salariés, montrer aux investisseurs, éduquer les clients, travailler avec les régulateurs et attirer des talents.');
insert into public.questions values('ia3',17,'Lequel de ces points n''est PAS un piège à éviter ?','["Attendre de l''IA qu''elle résolve tout", "Associer des talents techniques et des experts du métier pour choisir les projets", "Appliquer tel quel un planning traditionnel", "Attendre de recruter des superstars de l''IA pour commencer"]'::jsonb,1,'Associer ingénieurs et métier est la bonne pratique. Les autres pièges : compter sur deux ou trois ingénieurs seuls, espérer un succès du premier coup.');
insert into public.questions values('ia3',18,'Une épicerie découvre seule deux groupes de clients : étudiants (beaucoup de chips bon marché) et actifs (peu, mais chères). Quelle technique ?','["Un graphe de connaissances", "L''apprentissage supervisé", "L''apprentissage par renforcement", "L''apprentissage non supervisé (clustering)"]'::jsonb,3,'On ne donne pas de B : l''algorithme trouve lui-même des groupes dans les données. Utile pour segmenter un marché.');
insert into public.questions values('ia3',19,'Un modèle entraîné sur 100 000 images de voitures apprend à repérer les voiturettes de golf avec 1 000 images. C''est…','["Un GAN", "Du clustering", "Un graphe de connaissances", "De l''apprentissage par transfert"]'::jsonb,3,'On réutilise ce qui a été appris sur une tâche riche en données pour une tâche voisine qui en a peu.');
  insert into attempts(user_id, level_id) values (v_uid, p_level) returning id into v_id;
