-- =====================================================================
-- Thème « Intelligence artificielle » : 3 blocs de 20 questions (cours IA pour tous).
-- À coller dans Supabase → SQL Editor → Run. Réexécutable.
-- Corrige aussi le verrouillage pour qu'il se fasse thème par thème.
-- =====================================================================
begin;

   'Machine learning, deep learning, projets d''IA et transformation de l''entreprise : le cours IA pour tous.', '🧠', 'live')
on conflict (id) do update set ord=excluded.ord, title=excluded.title, descr=excluded.descr, icon=excluded.icon, status=excluded.status;
update public.themes set ord = 3 where id = 'a-venir-1';
update public.themes set ord = 4 where id = 'a-venir-2';

on conflict (id) do update set theme_id=excluded.theme_id, ord=excluded.ord, title=excluded.title, descr=excluded.descr, icon=excluded.icon, url=excluded.url, kind=excluded.kind;

-- Blocs IA : ord 101, 102, 103 (les blocs blockchain gardent 1 à 8)

delete from public.questions where level_id in ('ia1','ia2','ia3');

-- Verrouillage par thème : il faut avoir miné le bloc précédent DU MÊME THÈME
create or replace function public.start_attempt(p_level text)
returns bigint language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_id bigint; v_ord int; v_theme text; v_prev text;
begin
  if v_uid is null then raise exception 'non connecté'; end if;
  if not exists (select 1 from profiles where id = v_uid) then raise exception 'pseudo manquant'; end if;
  select ord, theme_id into v_ord, v_theme from levels where id = p_level;
  if v_ord is null then raise exception 'bloc inconnu'; end if;
  select id into v_prev from levels
    where theme_id is not distinct from v_theme and ord < v_ord order by ord desc limit 1;
  if v_prev is not null and not exists (
      select 1 from attempts a where a.user_id = v_uid and a.passed and a.level_id = v_prev) then
    raise exception 'bloc verrouillé';
  end if;
  if exists (select 1 from attempts where user_id = v_uid and created_at > now() - interval '10 seconds') then
    raise exception 'trop rapide, réessaie dans quelques secondes';
  end if;
  delete from attempts where user_id = v_uid and finished_at is null;
  return v_id;
end $$;
grant execute on function public.start_attempt(text) to authenticated;

-- Résumé par thème : les sessions Arcade IA ont un identifiant qui commence par « ia »
create or replace function public.my_summary()
returns table(theme_id text, blocs_mines bigint, blocs_total bigint, arcade_sessions bigint)
language sql stable security definer set search_path = public as $$
  select t.id,
    (select count(distinct a.level_id) from attempts a join levels l on l.id = a.level_id
      where a.user_id = auth.uid() and a.passed and l.theme_id = t.id),
    (select count(*) from levels l where l.theme_id = t.id),
    (select count(*) from arcade_scores s where s.user_id = auth.uid()
      and (case when s.session_id like 'ia%' then 'ia' else 'blockchain' end) = t.id)
  from themes t where t.status = 'live';
$$;
grant execute on function public.my_summary() to authenticated;

commit;
